						ctrlButton.Text = input.KeyCode.Name
						waitingForCtrl = false
						return
					end
					if gameProcessed then
						return
					end
					if boundKey and input.KeyCode == boundKey then
						if
							(boundKeyType == "Keyboard" and input.UserInputType == Enum.UserInputType.Keyboard)
							or (
								boundKeyType == "Gamepad"
