						Footer.Size = UDim2.new(1, -32, 0, 22)
						Footer.BackgroundTransparency = 1
						Footer.Text = "MWVANE SPEED BYPASS  /  CONFIG SAVED"
						Footer.TextColor3 = Color3.fromRGB(99, 96, 106)
