			if instaReset() then
				return
			end
			local prevAim = aceGuards.AimOn()
			if prevAim then
				if not aceGuards.DieIsOn() then
					aceGuards.autoDie = true
					aceGuards.SetDie(true)
				end
				if not aceGuards.FlingIsOn() then
					aceGuards.autoFling = true
					aceGuards.SetFling(true)
				end
			elseif aceGuards.prevAim then
				if aceGuards.autoDie then
					aceGuards.autoDie = false
					aceGuards.SetDie(false)
				end
				if aceGuards.autoFling then
					aceGuards.autoFling = false
					aceGuards.SetFling(false)
				end
			end
			aceGuards.prevAim = prevAim
			if imageLabel and imageLabel.AntiDie then
				pcall(imageLabel.AntiDie, aceGuards.DieIsOn())
			end
			if imageLabel and imageLabel.AntiFling then
				pcall(imageLabel.AntiFling, aceGuards.FlingIsOn())
			end
		end
		if aceGuards.watch then
			pcall(function()
				aceGuards.watch:Disconnect()
			end)
			aceGuards.watch = nil
		end
		aceGuards.watch = processOperation(RunService.Heartbeat, function()
			local now2 = os.clock()
			if now2 - aceGuards.last < 0.15 then
				return
			end
			aceGuards.last = now2
			aceGuards.Sync()
		end)
		aceGuards.Sync()
