					end
				end)
				pcall(function()
					if _G.stopAntiDie then
						_G.stopAntiDie()
					end
				end)
				for _, connection in ipairs(stateData) do
					pcall(function()
						connection:Disconnect()
					end)
				end
				stateData = {}
				_G._VantaGuardsRuntime = nil
			end,
		}
		if _G._VynxAntiDie == true then
			startAntiDie()
		end
	end
	processOperation()
end
